use vstd::prelude::*;

verus! {

fn remove_kth_element(list: &Vec<i32>, k: usize) -> (new_list: Vec<i32>)
    requires
        // Non-empty array
        list.len() > 0,
        // 1-based indexing constraint, and removing last element is not allowed
        1 <= k,
        k < list.len(),
    ensures
        // Length decreases by exactly 1
        new_list.len() == list.len() - 1,

        // Order-preserving removal of the k-th (1-based) element.
        // For all indices strictly before k (0-based: 0..k-1),
        // elements are unchanged.
        forall|i: int|
            0 <= i && i < (k as int - 1) ==> new_list[i] == list[i],

        // For all indices at/after k-1 in the new list,
        // they correspond to the element one position ahead in the old list.
        forall|i: int|
            (k as int - 1) <= i && i < new_list.len() ==> new_list[i] == list[i + 1],

        // Equivalent “prefix + suffix” characterization using sequences.
        new_list@ ==
            list@.subrange(0, (k as int - 1))
              + list@.subrange(k as int, list.len() as int),
{
    admit();
}

} // verus!